      <node TEXT="控制仓位，不重仓单只个股" />
      <node TEXT="设置止损，严格执行" />
      <node TEXT="实时监控盘面变化" />
      <node TEXT="及时调整仓位" />
    </node>
    <node TEXT="9.3 职业炒手的风险控制金句" POSITION="right">
